from math import radians, sin, cos, asin, sqrt

def dist_m(p, q):
    la1, lo1, la2, lo2 = map(radians, (*p, *q))
    h = sin((la2-la1)/2)**2 + cos(la1)*cos(la2)*sin((lo2-lo1)/2)**2
    return 2 * 6_371_000 * asin(sqrt(h))

def fare(m, base=500, base_m=1000, step=100, step_m=232):
    return base if m <= base_m else base + step * int(-(-(m - base_m) // step_m))

pts = [(35.660, 139.74, 0), (35.665, 139.74, 60), (35.670, 139.74, 120),
       (35.730, 139.74, 125), (35.675, 139.74, 180), (35.680, 139.74, 240)]
raw = sum(dist_m(pts[i-1][:2], pts[i][:2]) for i in range(1, len(pts)))
clean, prev = 0.0, pts[0]
for p in pts[1:]:
    d = dist_m(prev[:2], p[:2])
    if d / (p[2] - prev[2]) * 3.6 > 150:
        continue
    clean, prev = clean + d, p
print(f"raw   {raw:7.0f} m -> {fare(raw)} yen")
print(f"clean {clean:7.0f} m -> {fare(clean)} yen")

# raw     14455 m -> 6300 yen
# clean    2224 m -> 1100 yen
